.uv-twq {
  --c1: #2563eb;
  --c2: #f59e0b;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-twq {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  margin: 0;
  font-size: calc(var(--s) * 2.4);
  font-weight: 800;
  letter-spacing: -.03em;
  line-height: 1.15;
  text-align: center;
}

.uv-twq .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.uv-twq .cb {
  display: inline-grid;
  position: relative;
  height: 1.15em;
  vertical-align: bottom;
  perspective: 30em;
}

.uv-twq .cb i {
  grid-area: 1/1;
  padding: 0 .3em;
  visibility: hidden;
  font-style: normal;
  white-space: nowrap;
}

.uv-twq .in {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
  transform-origin: 50% 50% -.575em;
  animation: uv-twq calc(8s / var(--k)) cubic-bezier(.7,0,.2,1) infinite;
}

.uv-twq b {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-weight: inherit;
  color: #fff;
  border-radius: .2em;
  background: linear-gradient(135deg,var(--c1),color-mix(in srgb,var(--c1) 55%,var(--c2)));
  backface-visibility: hidden;
  transform-origin: 50% 50% -.575em;
  transform: rotateX(calc(var(--i) * -90deg));
}

.uv-twq b:nth-child(even) {
  background: linear-gradient(135deg,var(--c2),color-mix(in srgb,var(--c2) 55%,var(--c1)));
}

@keyframes uv-twq {
  0%,20% {
    transform: rotateX(0);
  }
  25%,45% {
    transform: rotateX(90deg);
  }
  50%,70% {
    transform: rotateX(180deg);
  }
  75%,95% {
    transform: rotateX(270deg);
  }
  100% {
    transform: rotateX(360deg);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-twq,.uv-twq *,.uv-twq *::before,.uv-twq *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

