.uvq14-ink {
  --c1: #0f766e;
  --c2: #2b2d31;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq14-ink {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 17.5em;
  padding: .9em .9em .7em;
  border-radius: 1.5em;
  background: linear-gradient(160deg,color-mix(in srgb,var(--c2) 80%,#fff),var(--c2) 40%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.12),0 1.6em 2.6em -1.4em rgba(0,0,0,.55);
}

.uvq14-ink .scr {
  position: relative;
  height: 15.5em;
  padding: 1em 1.15em .8em;
  border-radius: .35em;
  color: #1b1b1b;
  background: #e8e6de;
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.25),inset 0 .2em .5em rgba(0,0,0,.12);
  overflow: hidden;
  cursor: pointer;
  display: flex;
  flex-direction: column;
}

.uvq14-ink .hd {
  display: flex;
  justify-content: space-between;
  gap: 1em;
  margin: 0 0 .9em;
  font-size: .62em;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  opacity: .65;
}

.uvq14-ink .pg {
  position: relative;
  flex: 1;
}

.uvq14-ink .pg p {
  margin: 0;
  font: 400 .92em/1.6 "Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  text-align: justify;
  hyphens: auto;
}

.uvq14-ink .pg p:first-of-type+p::first-letter {
  float: left;
  margin: .08em .12em 0 0;
  font-size: 2.6em;
  line-height: .8;
  font-weight: 700;
}

.uvq14-ink .gh {
  position: absolute;
  inset: 0;
  opacity: 0;
  pointer-events: none;
}

.uvq14-ink .ft {
  display: flex;
  align-items: center;
  gap: .8em;
  font-size: .62em;
  font-weight: 600;
  opacity: .7;
}

.uvq14-ink .br {
  flex: 1;
  height: .3em;
  border-radius: 1em;
  background: rgba(0,0,0,.12);
  overflow: hidden;
}

.uvq14-ink .br i {
  display: block;
  height: 100%;
  width: calc(var(--q,.333) * 100%);
  background: #1b1b1b;
  transition: width calc(0.3s / var(--k)) steps(3);
}

.uvq14-ink .fx {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  opacity: 0;
}

.uvq14-ink.flash .fx {
  animation: uvq14-ink-f calc(0.5s / var(--k)) steps(1,end);
}

.uvq14-ink.flash .gh {
  animation: uvq14-ink-g calc(2s / var(--k)) ease-out;
}

.uvq14-ink.nope .scr {
  animation: uvq14-ink-n calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq14-ink .ct {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: .6em;
}

.uvq14-ink .ct button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 2.6em;
  height: 1.8em;
  border-radius: .6em;
  color: #d4d4d8;
  background: rgba(255,255,255,.08);
  transition: background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.2s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq14-ink .ct button:hover {
  background: rgba(255,255,255,.16);
}

.uvq14-ink .ct button:active {
  transform: scale(.92);
}

.uvq14-ink .ct button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq14-ink .ct svg {
  width: 1.1em;
  height: 1.1em;
}

.uvq14-ink .lg {
  width: 2.4em;
  height: .3em;
  border-radius: 1em;
  background: rgba(255,255,255,.14);
}

@keyframes uvq14-ink-f {
  0% {
    opacity: 1;
    background: #111;
  }
  30% {
    opacity: 1;
    background: #e8e6de;
  }
  55% {
    opacity: 1;
    background: #2a2a2a;
  }
  80% {
    opacity: 0;
  }
}

@keyframes uvq14-ink-g {
  from {
    opacity: .13;
  }
  to {
    opacity: 0;
  }
}

@keyframes uvq14-ink-n {
  25% {
    transform: translateX(-.25em);
  }
  75% {
    transform: translateX(.25em);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq14-ink,.uvq14-ink *,.uvq14-ink *::before,.uvq14-ink *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

