document.querySelectorAll(".uvq14-ink").forEach(el => {
  const ps=[...el.querySelectorAll(".pg p:not(.gh)")],gh=el.querySelector(".gh"),n=el.querySelector(".n"),scr=el.querySelector(".scr");let i=0;
const flash=c=>{el.classList.remove(c);void el.offsetWidth;el.classList.add(c)};
const go=d=>{const j=i+d;if(j<0||j>=ps.length){flash("nope");return}gh.textContent=ps[i].textContent;ps[i].hidden=true;i=j;ps[i].hidden=false;n.textContent=String(i+1);el.style.setProperty("--q",((i+1)/ps.length).toFixed(3));flash("flash")};
el.querySelector(".pv").addEventListener("click",()=>go(-1));el.querySelector(".nx").addEventListener("click",()=>go(1));
scr.addEventListener("click",e=>{const r=scr.getBoundingClientRect();go(e.clientX-r.left<r.width*.35?-1:1)});
el.addEventListener("keydown",e=>{if(e.key==="ArrowRight"||e.key==="PageDown"){e.preventDefault();go(1)}if(e.key==="ArrowLeft"||e.key==="PageUp"){e.preventDefault();go(-1)}});
el.addEventListener("animationend",e=>{if(e.target===el.querySelector(".fx"))el.classList.remove("flash")})
});

