.uvq14-wav {
  --c1: #0369a1;
  --c2: #f59e0b;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq14-wav {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 17em;
  border-radius: 1.3em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent);
}

.uvq14-wav .sc {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  outline: 0;
}

.uvq14-wav .tr {
  height: 320%;
}

.uvq14-wav .st {
  position: sticky;
  top: 0;
  height: 17em;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: radial-gradient(90% 70% at 50% 110%,color-mix(in srgb,var(--c2) 22%,transparent),transparent 70%);
}

.uvq14-wav svg {
  width: 100%;
  height: auto;
  overflow: visible;
}

.uvq14-wav .g {
  fill: none;
  stroke: color-mix(in srgb,var(--fg) 14%,transparent);
  stroke-width: 1.2;
  stroke-dasharray: 3 6;
}

.uvq14-wav .t1 {
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -.5px;
  fill: color-mix(in srgb,var(--c1) 82%,var(--fg));
}

.uvq14-wav .t2 {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  fill: var(--c2);
}

.uvq14-wav .pc {
  position: absolute;
  left: 1.2em;
  right: 1.2em;
  top: 1em;
  height: .25em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 7%,transparent);
}

.uvq14-wav .pc i {
  display: block;
  height: 100%;
  width: calc(var(--p,0) * 100%);
  border-radius: inherit;
  background: var(--c1);
}

.uvq14-wav .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.uvq14-wav .hn {
  position: absolute;
  left: 50%;
  bottom: .8em;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: .3em;
  padding: .35em .7em;
  border-radius: 2em;
  font-size: .7em;
  font-weight: 700;
  color: var(--bg);
  background: var(--fg);
  translate: -50% 0;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
  animation: uvq14-wav-h calc(1.6s / var(--k)) ease-in-out infinite;
}

.uvq14-wav .hn svg {
  width: 1.1em;
  height: 1.1em;
}

.uvq14-wav.moved .hn {
  opacity: 0;
}

.uvq14-wav .sc:focus-visible {
  box-shadow: inset 0 0 0 2px var(--c1);
  border-radius: 1.3em;
}

@keyframes uvq14-wav-h {
  50% {
    transform: translateY(.25em);
  }
}

