css:
.uvq14-riso {
  --c1: #ff48b0;
  --c2: #0078bf;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq14-riso {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 19em;
  display: grid;
  justify-items: center;
  gap: 1em;
}

.uvq14-riso .pp {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  padding: 1.1em 1.2em 1em;
  color: #2b2b2b;
  background: #f4efe3;
  box-shadow: 0 .1em .2em rgba(0,0,0,.1),0 1.2em 2em -1.2em rgba(0,0,0,.35);
  overflow: hidden;
  --bx: .05em;
  --by: .035em;
  --ax: 0em;
  --ay: 0em;
}

.uvq14-riso .pp::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(rgba(60,40,10,.12) .6px,transparent .8px) 0 0/5px 5px,radial-gradient(rgba(60,40,10,.08) .6px,transparent .8px) 2px 3px/7px 7px;
  mix-blend-mode: multiply;
}

.uvq14-riso .kc,.uvq14-riso .ft {
  margin: 0;
  font: 600 .62em/1.3 ui-monospace,"SF Mono","JetBrains Mono",Menlo,Consolas,monospace;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.uvq14-riso .ft {
  display: flex;
  justify-content: space-between;
  margin-top: .8em;
  color: var(--c2);
}

.uvq14-riso .kc {
  color: var(--c1);
  mix-blend-mode: multiply;
}

.uvq14-riso .hl {
  display: grid;
  margin: .35em 0 0;
  font: 900 calc(var(--s) * 3.3)/.88 "Arial Black","Helvetica Neue",Arial,sans-serif;
  letter-spacing: -.05em;
  text-transform: uppercase;
}

.uvq14-riso .a,.uvq14-riso .b {
  grid-area: 1/1;
  mix-blend-mode: multiply;
  transition: transform calc(0.35s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq14-riso .a {
  color: var(--c1);
  transform: translate(var(--ax),var(--ay));
}

.uvq14-riso .b {
  color: var(--c2);
  transform: translate(var(--bx),var(--by));
  -webkit-mask: radial-gradient(circle,#000 55%,transparent 62%) 0 0/.075em .075em;
  mask: radial-gradient(circle,#000 55%,transparent 62%) 0 0/.075em .075em;
}

.uvq14-riso.feed .pp {
  animation: uvq14-riso-f calc(0.7s / var(--k)) steps(7,end);
}

.uvq14-riso .rp {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .55em 1.1em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 700;
  color: var(--bg);
  background: var(--fg);
  transition: transform calc(0.25s / var(--k)) cubic-bezier(.34,1.56,.64,1),opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq14-riso .rp:hover {
  transform: translateY(-2px);
}

.uvq14-riso .rp:active {
  transform: scale(.95);
}

.uvq14-riso .rp:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@keyframes uvq14-riso-f {
  from {
    clip-path: inset(0 0 100% 0);
    transform: translateY(-.4em);
  }
  to {
    clip-path: inset(0);
    transform: none;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq14-riso,.uvq14-riso *,.uvq14-riso *::before,.uvq14-riso *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

