css:
.uvq14-nb {
  --c1: #1d4ed8;
  --c2: #dc2626;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq14-nb {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 19em;
  display: grid;
  justify-items: center;
  gap: 1em;
}

.uvq14-nb .pg {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  padding: .9em 1em 1.3em 3em;
  color: var(--c1);
  background: linear-gradient(90deg,transparent 2.3em,rgba(220,38,38,.55) 2.3em 2.4em,transparent 2.4em),repeating-linear-gradient(transparent 0 calc(1.9em - 1px),#a9c7e8 calc(1.9em - 1px) 1.9em) 0 .9em/100% 100% no-repeat,#fffdf6;
  border-radius: .2em .6em .6em .2em;
  box-shadow: 0 .1em .2em rgba(0,0,0,.08),0 1.2em 2em -1.2em rgba(0,0,0,.35);
  font-family: "Segoe Print","Bradley Hand","Chalkboard SE","Comic Sans MS",cursive;
}

.uvq14-nb .pg::before {
  content: "";
  position: absolute;
  left: .8em;
  top: 1.4em;
  bottom: 1.4em;
  width: .7em;
  background: radial-gradient(circle,var(--bg) .3em,transparent .32em) 0 0/.7em 3.8em repeat-y;
}

.uvq14-nb .dt {
  margin: 0;
  height: 1.9em;
  line-height: 1.9em;
  font-size: .72em;
  text-align: right;
  color: #6b7280;
}

.uvq14-nb h3,.uvq14-nb li {
  margin: 0;
  height: 1.9em;
  line-height: 1.9em;
  font-weight: 700;
}

.uvq14-nb h3 {
  font-size: 1.15em;
  line-height: 1.65em;
  height: 1.65em;
}

.uvq14-nb ul {
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 1em;
}

.uvq14-nb li::before {
  content: "·";
  margin-right: .4em;
}

.uvq14-nb .w {
  position: relative;
  display: inline-block;
}

.uvq14-nb .t {
  display: inline-block;
  clip-path: inset(-20% 100% -20% 0);
}

.uvq14-nb .pn {
  position: absolute;
  left: 0;
  bottom: .35em;
  width: .32em;
  height: 1.7em;
  border-radius: .1em .1em 0 0;
  opacity: 0;
  transform-origin: 50% 100%;
  rotate: 28deg;
  background: linear-gradient(transparent 0 76%,#e7c79c 76% 90%,#333 90%),linear-gradient(90deg,#f5b800 0 50%,#e0a400 50%);
  clip-path: polygon(0 0,100% 0,100% 76%,50% 100%,0 76%);
}

.uvq14-nb.on .t {
  animation: uvq14-nb-w calc(1s / var(--k)) linear calc(var(--i) * calc(1.05s / var(--k))) forwards;
}

.uvq14-nb.on .pn {
  animation: uvq14-nb-p calc(1s / var(--k)) linear calc(var(--i) * calc(1.05s / var(--k))) both;
}

.uvq14-nb .dn .w::after {
  content: "";
  position: absolute;
  left: -.15em;
  right: -.15em;
  top: 52%;
  height: .13em;
  border-radius: 1em;
  background: var(--c2);
  transform: scaleX(0);
  transform-origin: 0 50%;
  rotate: -1.5deg;
}

.uvq14-nb.on .dn .w::after {
  animation: uvq14-nb-s calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1) calc(calc(4.3s / var(--k)) + var(--i) * calc(0.3s / var(--k))) forwards;
}

.uvq14-nb .rw {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .55em 1.1em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 700;
  color: var(--bg);
  background: var(--fg);
  transition: transform calc(0.25s / var(--k)) cubic-bezier(.34,1.56,.64,1),opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq14-nb .rw:hover {
  transform: translateY(-2px);
}

.uvq14-nb .rw:active {
  transform: scale(.95);
}

.uvq14-nb .rw:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@keyframes uvq14-nb-w {
  to {
    clip-path: inset(-20% -5% -20% 0);
  }
}

@keyframes uvq14-nb-p {
  0% {
    left: 0;
    opacity: 1;
  }
  96% {
    left: 100%;
    opacity: 1;
  }
  100% {
    left: 100%;
    opacity: 0;
  }
}

@keyframes uvq14-nb-s {
  to {
    transform: scaleX(1);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq14-nb,.uvq14-nb *,.uvq14-nb *::before,.uvq14-nb *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

