  const go=()=>{el.classList.remove("on");void el.offsetWidth;el.classList.add("on")};const io=new IntersectionObserver(es=>{if(es[0].isIntersecting){go();io.disconnect()}},{threshold:.5});io.observe(el);el.querySelector(".rw").addEventListener("click",go);return()=>io.disconnect()
});

