.uvq14-cur {
  --c1: #14532d;
  --c2: #d9f99d;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq14-cur {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 22em;
  height: 17em;
  border-radius: 1.3em;
  overflow: hidden;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 10%,transparent);
  background: var(--c1);
}

.uvq14-cur .sc {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  outline: 0;
  scrollbar-width: none;
}

.uvq14-cur .cd {
  position: relative;
  z-index: 1;
  min-height: 19em;
  padding: 1.4em 1.4em 2em;
  border-radius: 0 0 1.3em 1.3em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 1em 1.6em -.6em rgba(0,0,0,.45);
}

.uvq14-cur .kc {
  margin: 0;
  font-size: .68em;
  font-weight: 700;
  letter-spacing: .14em;
  text-transform: uppercase;
  color: color-mix(in srgb,var(--fg) 58%,transparent);
}

.uvq14-cur h3 {
  margin: .4em 0 .6em;
  font-size: 1.6em;
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -.03em;
}

.uvq14-cur .cd p:not(.kc) {
  margin: 0 0 .8em;
  font-size: .88em;
  line-height: 1.6;
  color: color-mix(in srgb,var(--fg) 58%,transparent);
}

.uvq14-cur .ft {
  position: sticky;
  bottom: 0;
  z-index: 0;
  height: 9em;
  box-sizing: border-box;
  padding: 1em 1.2em 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  color: var(--c2);
  background: var(--c1);
  overflow: hidden;
}

.uvq14-cur nav {
  display: flex;
  gap: 1em;
  font-size: .78em;
  font-weight: 600;
}

.uvq14-cur nav a {
  color: inherit;
  text-decoration: none;
  opacity: .8;
  border-radius: .2em;
  transition: opacity calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq14-cur nav a:hover {
  opacity: 1;
  text-decoration: underline;
}

.uvq14-cur nav a:focus-visible {
  outline: 2px solid var(--c2);
  outline-offset: 3px;
  opacity: 1;
}

.uvq14-cur .wm {
  display: flex;
  justify-content: space-between;
  margin: 0 -.04em -.17em;
  font-weight: 900;
  line-height: 1;
  letter-spacing: -.05em;
  text-transform: uppercase;
}

.uvq14-cur .wm b {
  display: block;
  font-weight: inherit;
  transform: translateY(calc((1 - clamp(0,var(--r,0) * 1.6 - var(--i) * .09,1)) * 105%));
}

.uvq14-cur .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.uvq14-cur .hn {
  position: absolute;
  left: 50%;
  bottom: .8em;
  z-index: 5;
  display: flex;
  align-items: center;
  gap: .3em;
  padding: .35em .7em;
  border-radius: 2em;
  font-size: .7em;
  font-weight: 700;
  color: var(--bg);
  background: var(--fg);
  translate: -50% 0;
  pointer-events: none;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
  animation: uvq14-cur-h calc(1.6s / var(--k)) ease-in-out infinite;
}

.uvq14-cur .hn svg {
  width: 1.1em;
  height: 1.1em;
}

.uvq14-cur.moved .hn {
  opacity: 0;
}

.uvq14-cur .sc:focus-visible {
  box-shadow: inset 0 0 0 2px var(--c1);
  border-radius: 1.3em;
}

@keyframes uvq14-cur-h {
  50% {
    transform: translateY(.25em);
  }
}

.uvq14-cur .hn {
  color: var(--c1);
  background: var(--c2);
}

