  background: radial-gradient(circle var(--rr) at var(--x) var(--y),color-mix(in srgb,var(--c1) 55%,#fff8e6),color-mix(in srgb,var(--c1) 70%,#7a5a20) 70%,#3a2c14),repeating-linear-gradient(0deg,rgba(0,0,0,.08) 0 1px,transparent 1px 1.6em),repeating-linear-gradient(90deg,rgba(0,0,0,.06) 0 1px,transparent 1px 3.2em);
