  mask: radial-gradient(circle var(--rr) at var(--x) var(--y),#000 55%,transparent 100%);
  pointer-events: none;
}

.uvq14-fl .kc {
  margin: 0;
  font: 700 .66em/1 ui-monospace,"SF Mono","JetBrains Mono",Menlo,Consolas,monospace;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.uvq14-fl h3 {
  margin: .45em 0 .4em;
  font-size: 1.8em;
  font-weight: 900;
  line-height: 1.02;
  letter-spacing: -.03em;
}

.uvq14-fl .tx p:last-child,.uvq14-fl .lit p:last-child {
  margin: 0;
  font-size: .85em;
  line-height: 1.55;
}

