const put=()=>{el.style.setProperty("--x",x.toFixed(1)+"px");el.style.setProperty("--y",y.toFixed(1)+"px")};
const wander=()=>{const t=(performance.now()-t0)/1000,W=el.offsetWidth,H=el.offsetHeight;x=W/2+Math.sin(t*.7)*W*.32;y=H/2+Math.sin(t*1.1+1)*H*.28;put();raf=idle?requestAnimationFrame(wander):0};
const wake=()=>{idle=false;cancelAnimationFrame(raf);raf=0;clearTimeout(tm);tm=setTimeout(()=>{if(document.activeElement!==el&&!rm){idle=true;wander()}},2600)};
